class Solution:
    def fractionToDecimal(self, numerator: int, denominator: int) -> str:
        if numerator == 0:
            return "0"

        sign = "-" if (numerator < 0) ^ (denominator < 0) else ""
        num = abs(numerator)
        den = abs(denominator)

        result = []
        if sign:
            result.append(sign)

        integer_part = num // den
        result.append(str(integer_part))

        remainder = num % den
        if remainder == 0:
            return "".join(result)

        result.append(".")

        seen = {}
        while remainder != 0:
            if remainder in seen:
                idx = seen[remainder]
                non_repeating = "".join(result[:idx])
                repeating = "".join(result[idx:])
                return non_repeating + "(" + repeating + ")"

            seen[remainder] = len(result)
            remainder *= 10
            digit = remainder // den
            result.append(str(digit))
            remainder %= den

        return "".join(result)

import sys

def main():
    try:
        line1 = sys.stdin.readline().strip()
        line2 = sys.stdin.readline().strip()
        if not line1 or not line2:
            return
        numerator = int(line1)
        denominator = int(line2)
        sol = Solution()
        print(sol.fractionToDecimal(numerator, denominator))
    except ValueError:
        pass

if __name__ == "__main__":
    main()
